INSERT INTO "meetings" ("id", "title", "description", "scheduledAt", "endAt", "location", "meetingLink", "status", "type", "domainId", "minutesContent", "decisionsContent", "actionsContent", "invitesSentAt", "createdAt", "updatedAt", "teamsMeetingId", "teamsJoinUrl", "teamsAttendanceSyncedAt") VALUES (1, 'Reunião Ordinária do Comitê de Dados — Março 2025', 'Reunião mensal do Comitê de Dados para revisão do progresso dos domínios, aprovação de políticas e deliberação sobre solicitações de acesso pendentes.', '2026-03-02 04:08:30', '2026-03-02 06:08:30', 'Sala de Reuniões 4A — Torre Corporativa, São Paulo', NULL, 'realizada', 'ordinaria', NULL, '**Ata da Reunião Ordinária — Março 2025**\n\nA reunião foi aberta às 09h05 pela Presidente do Comitê, Ana Paula Ferreira (Data Owner — Dados Comerciais), com a presença de 14 dos 17 membros convocados.\n\n**1. Aprovação da ata anterior**\nA ata da reunião de fevereiro foi aprovada por unanimidade, com a correção de um erro tipográfico no item 3.2 referente ao prazo de implementação do catálogo de dados.\n\n**2. Revisão do progresso por domínio**\nCarlos Eduardo Lima (Data Steward — Dados Comerciais) apresentou o painel de progresso atualizado. Os domínios Dados Comerciais (78%) e Dados Financeiros (65%) apresentam evolução satisfatória. O domínio Dados de Sustentabilidade (32%) requer atenção especial, com gargalo identificado na etapa de catalogação de ativos.\n\n**3. Política de Classificação de Dados**\nApós debate, o Comitê aprovou por maioria (11 votos a favor, 2 abstenções) a Política de Classificação de Dados v2.1, que introduz o nível "Restrito — Regulatório" para dados sujeitos à LGPD e normas da ANM.\n\n**4. Solicitações de acesso**\nForam analisadas 4 solicitações de acesso a dados de produção oriundas da área de Planejamento Estratégico. Três foram aprovadas com restrições de visualização; uma foi encaminhada para análise adicional de segurança.\n\n**5. Encerramento**\nA reunião foi encerrada às 11h20. Próxima reunião ordinária agendada para abril de 2025.', '1. **Aprovação da Política de Classificação de Dados v2.1** — Vigência imediata. Responsável pela comunicação: Mariana Costa Souza. Prazo: 15/04/2025.\n\n2. **Aprovação de 3 solicitações de acesso** a dados de produção para a equipe de Planejamento Estratégico, com perfil somente-leitura e auditoria habilitada.\n\n3. **Encaminhamento para análise de segurança** da solicitação REQ-2025-0847 (acesso a dados de custos de produção por unidade fabril). Responsável: Rafael Cardoso. Prazo: 31/03/2025.\n\n4. **Criação de grupo de trabalho** para elaboração do Glossário de Negócios do domínio Dados de Sustentabilidade. Coordenador: Thiago Mendes. Prazo: 30/04/2025.', '| # | Ação | Responsável | Prazo | Status |\n|---|------|-------------|-------|--------|\n| 1 | Publicar Política de Classificação v2.1 no portal interno | Mariana Costa Souza | 15/04/2025 | Concluído |\n| 2 | Provisionar acessos aprovados no AD | Rafael Cardoso | 22/03/2025 | Concluído |\n| 3 | Concluir análise de segurança REQ-2025-0847 | Rafael Cardoso | 31/03/2025 | Concluído |\n| 4 | Convocar membros para GT Glossário Sustentabilidade | Thiago Mendes | 05/04/2025 | Concluído |\n| 5 | Atualizar roadmap do domínio Sustentabilidade | Fernanda Oliveira | 30/04/2025 | Em andamento |', '2026-02-23 04:08:30', '2026-04-23 07:08:30', '2026-04-23 07:08:30', NULL, NULL, NULL);
INSERT INTO "meetings" ("id", "title", "description", "scheduledAt", "endAt", "location", "meetingLink", "status", "type", "domainId", "minutesContent", "decisionsContent", "actionsContent", "invitesSentAt", "createdAt", "updatedAt", "teamsMeetingId", "teamsJoinUrl", "teamsAttendanceSyncedAt") VALUES (2, 'Reunião Ordinária do Comitê de Dados — Abril 2025', 'Reunião mensal com foco em qualidade de dados, revisão do catálogo de ativos e deliberação sobre o projeto de integração de dados de logística.', '2026-04-01 03:08:30', '2026-04-01 05:38:30', 'Microsoft Teams — Link enviado por e-mail', NULL, 'realizada', 'ordinaria', NULL, '**Ata da Reunião Ordinária — Abril 2025**\n\nReunião realizada em formato híbrido (presencial + Teams). Presidida por Ana Paula Ferreira. Quórum: 15/17 membros presentes.\n\n**1. Aprovação da ata de março**\nAprovada sem ressalvas.\n\n**2. Qualidade de Dados — Relatório Trimestral Q1 2025**\nCamila Torres (Data Steward) apresentou o relatório de qualidade de dados referente ao Q1 2025. Destaques: completude média de 87% nos domínios monitorados; acurácia de 94% nos dados de produção; 3 incidentes de qualidade registrados e resolvidos no período.\n\n**3. Catálogo de Ativos de Dados**\nPaulo Henrique Santos apresentou o status do catálogo: 1.247 ativos catalogados de um universo estimado de 2.100. Meta de 80% de cobertura até junho/2025. Identificada necessidade de treinamento das equipes de TI para aceleração do processo.\n\n**4. Projeto de Integração — Dados de Logística**\nRoberto Alves Neto apresentou o escopo do projeto de integração entre o ERP (SAP) e o data lake para dados de logística. O Comitê aprovou o início da fase de análise, com orçamento preliminar de R$ 380.000. Ticket ServiceNow #INC0045231 aberto para acompanhamento.\n\n**5. LGPD — Atualização do mapeamento de dados pessoais**\nLuciana Pinto informou que o mapeamento de dados pessoais foi atualizado para incluir os novos formulários de RH digitalizados. 12 novos fluxos de dados pessoais identificados e documentados.', '1. **Aprovação do início da fase de análise** do Projeto de Integração Logística (SAP → Data Lake). Orçamento preliminar: R$ 380.000. Gestor do projeto: Roberto Alves Neto.\n\n2. **Aprovação do plano de treinamento** em catalogação de dados para equipes de TI. 3 turmas de 15 pessoas. Período: maio/junho 2025. Responsável: Paulo Henrique Santos.\n\n3. **Determinação de revisão** do processo de tratamento de dados pessoais em RH, com prazo de adequação até 30/06/2025. Responsável: Luciana Pinto.\n\n4. **Meta de qualidade** estabelecida: completude mínima de 90% e acurácia mínima de 95% para todos os domínios críticos até Q3 2025.', '| # | Ação | Responsável | Prazo | Status |\n|---|------|-------------|-------|--------|\n| 1 | Formalizar escopo do Projeto Integração Logística | Roberto Alves Neto | 30/04/2025 | Concluído |\n| 2 | Contratar empresa de treinamento em catalogação | Paulo Henrique Santos | 15/05/2025 | Em andamento |\n| 3 | Revisar processos de dados pessoais em RH | Luciana Pinto | 30/06/2025 | Em andamento |\n| 4 | Publicar relatório Q1 de qualidade no portal | Camila Torres | 25/04/2025 | Concluído |\n| 5 | Atualizar catálogo com 200 novos ativos | Equipe TI | 31/05/2025 | Em andamento |', '2026-03-25 03:08:30', '2026-04-23 07:08:30', '2026-04-23 07:08:30', NULL, NULL, NULL);
INSERT INTO "meetings" ("id", "title", "description", "scheduledAt", "endAt", "location", "meetingLink", "status", "type", "domainId", "minutesContent", "decisionsContent", "actionsContent", "invitesSentAt", "createdAt", "updatedAt", "teamsMeetingId", "teamsJoinUrl", "teamsAttendanceSyncedAt") VALUES (3, 'Workshop de Qualidade de Dados — Domínio Financeiro', 'Workshop técnico para definição de regras de qualidade, métricas de monitoramento e SLAs de dados para o domínio Financeiro.', '2026-03-19 03:08:30', '2026-03-19 07:08:30', 'Sala de Treinamento B2 — Torre Corporativa', NULL, 'realizada', 'workshop', 3, '**Ata do Workshop de Qualidade de Dados — Domínio Financeiro**\n\nWorkshop conduzido por Mariana Costa Souza (Data Owner — Dados Financeiros) com participação de 8 especialistas do domínio e 2 representantes de TI.\n\n**Resultados do Workshop:**\n\n**Dimensões de qualidade priorizadas:**\n- Completude: campos obrigatórios em lançamentos contábeis (meta: 100%)\n- Acurácia: conciliação automática com sistemas legados (meta: 99,5%)\n- Consistência: uniformidade de centros de custo entre ERP e BI (meta: 98%)\n- Pontualidade: fechamento contábil até D+2 (meta: 95% dos períodos)\n\n**Regras de qualidade definidas:**\n- 47 regras de validação mapeadas para dados de lançamentos contábeis\n- 23 regras para dados de orçamento vs. realizado\n- 12 regras para dados de fluxo de caixa\n\n**SLAs estabelecidos:**\n- Dados de fechamento mensal: disponíveis até D+3 após fechamento\n- Dados de orçamento: atualizados semanalmente às sextas-feiras\n- Alertas de qualidade: notificação em até 4 horas após detecção de anomalia', '1. **Aprovação do framework de qualidade** para o domínio Financeiro com 82 regras de validação.\n2. **SLAs formalizados** e publicados no catálogo de dados.\n3. **Implementação de dashboard de qualidade** específico para o domínio Financeiro até 31/05/2025.', '| # | Ação | Responsável | Prazo | Status |\n|---|------|-------------|-------|--------|\n| 1 | Implementar as 47 regras de validação no pipeline | Equipe TI | 31/05/2025 | Em andamento |\n| 2 | Criar dashboard de qualidade Financeiro | Mariana Costa Souza | 31/05/2025 | Em andamento |\n| 3 | Documentar SLAs no catálogo de dados | Carlos Eduardo Lima | 15/04/2025 | Concluído |', '2026-03-12 03:08:30', '2026-04-23 07:08:30', '2026-04-23 07:08:30', NULL, NULL, NULL);
INSERT INTO "meetings" ("id", "title", "description", "scheduledAt", "endAt", "location", "meetingLink", "status", "type", "domainId", "minutesContent", "decisionsContent", "actionsContent", "invitesSentAt", "createdAt", "updatedAt", "teamsMeetingId", "teamsJoinUrl", "teamsAttendanceSyncedAt") VALUES (4, 'Reunião Piloto — Governança de Dados de IA', 'Reunião piloto para estruturar o processo de governança de modelos de IA e dados de treinamento utilizados na Votorantim Cimentos.', '2026-04-13 03:08:30', '2026-04-13 04:38:30', 'Microsoft Teams', NULL, 'realizada', 'piloto', NULL, '**Ata da Reunião Piloto — Governança de Dados de IA**\n\nReunião conduzida por Ana Paula Ferreira. Participação de 10 membros do Comitê e 3 especialistas externos em IA/ML convidados.\n\nContexto:\nA Votorantim Cimentos utiliza atualmente 7 modelos de IA em produção (previsão de demanda, otimização de forno, controle de qualidade, manutenção preditiva, entre outros). A ausência de um framework de governança específico para IA representa um risco regulatório e operacional crescente.\n\nDiscussões:\n- Apresentação do inventário de modelos de IA em produção\n- Análise de riscos: viés algorítmico, explicabilidade, deriva de modelo\n- Benchmarking com frameworks internacionais (EU AI Act, NIST AI RMF)\n- Proposta de estrutura de papéis: AI Owner, AI Steward, AI Ethics Officer\n\nPróximos passos:\nO Comitê decidiu criar uma subcomissão de Governança de IA, com reunião de constituição prevista para maio/2025.', '1. Criação da Subcomissão de Governança de IA com 5 membros permanentes e reuniões mensais.\n2. Adoção do NIST AI RMF como framework de referência para governança de IA.\n3. Inventário completo de modelos de IA a ser concluído até 31/05/2025.', '| # | Ação | Responsável | Prazo | Status |\n|---|------|-------------|-------|--------|\n| 1 | Constituir Subcomissão de Governança de IA | Ana Paula Ferreira | 15/05/2025 | Em andamento |\n| 2 | Completar inventário de modelos de IA | Diego Barbosa | 31/05/2025 | Em andamento |\n| 3 | Elaborar proposta de política de IA | Subcomissão | 30/06/2025 | Pendente |', '2026-04-06 03:08:30', '2026-04-23 07:08:30', '2026-04-23 07:16:48', NULL, NULL, NULL);
INSERT INTO "meetings" ("id", "title", "description", "scheduledAt", "endAt", "location", "meetingLink", "status", "type", "domainId", "minutesContent", "decisionsContent", "actionsContent", "invitesSentAt", "createdAt", "updatedAt", "teamsMeetingId", "teamsJoinUrl", "teamsAttendanceSyncedAt") VALUES (5, 'Reunião Ordinária do Comitê de Dados — Maio 2025', 'Reunião mensal com pauta: revisão de indicadores Q1, aprovação do orçamento de dados para H2/2025, deliberação sobre política de retenção de dados e constituição da Subcomissão de IA.', '2026-04-30 03:08:30', '2026-04-30 05:08:30', 'Sala de Reuniões 4A — Torre Corporativa / Microsoft Teams (híbrido)', NULL, 'agendada', 'ordinaria', NULL, NULL, NULL, NULL, '2026-04-23 03:08:30', '2026-04-23 07:08:31', '2026-04-23 07:08:31', NULL, NULL, NULL);
