INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (1, 'INC0045231', 'Integração SAP → Data Lake — Dados de Logística', 'Implementação do pipeline de integração entre o módulo de logística do SAP S/4HANA e o Data Lake corporativo. Escopo inclui dados de transporte, armazenagem e distribuição de cimento. Aprovado pelo Comitê de Dados em abril/2025. Orçamento: R$ 380.000.', 'Em Andamento', 'Alta', 'Roberto Alves Neto', 5, 4, 6, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=incident.do?sys_id=INC0045231', '2026-04-21 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (2, 'INC0044892', 'Implementação de Regras de Qualidade — Domínio Financeiro', 'Implementação das 82 regras de validação de qualidade de dados aprovadas no Workshop de Qualidade do Domínio Financeiro (abril/2025). Inclui 47 regras para lançamentos contábeis, 23 para orçamento vs. realizado e 12 para fluxo de caixa.', 'Em Andamento', 'Alta', 'Paulo Henrique Santos', 3, 8, 3, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=incident.do?sys_id=INC0044892', '2026-04-22 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (3, 'INC0045018', 'Provisionar Acessos Aprovados — Planejamento Estratégico', 'Provisionamento de acessos a dados de produção para 3 analistas da equipe de Planejamento Estratégico, conforme aprovação do Comitê de Dados em março/2025. Perfil: somente-leitura com auditoria habilitada.', 'Resolvido', 'Média', 'Rafael Cardoso', 2, 12, 6, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=incident.do?sys_id=INC0045018', '2026-04-03 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (4, 'INC0044756', 'Análise de Segurança — Acesso a Dados de Custos por Unidade Fabril', 'Análise de segurança da solicitação REQ-2025-0847: acesso a dados de custos de produção por unidade fabril para equipe de Controladoria. Verificação de conformidade com política de classificação de dados e LGPD.', 'Resolvido', 'Alta', 'Rafael Cardoso', 3, 12, 6, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=incident.do?sys_id=INC0044756', '2026-03-29 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (5, 'INC0045387', 'Incidente de Qualidade — Dados de Eficiência de Forno (Cantagalo)', 'Incidente de qualidade detectado nos dados de eficiência de forno da planta de Cantagalo. Desvio de ±3,2% na leitura de temperatura do clínquer entre o sistema SCADA e o data lake. Impacto: 48h de dados comprometidos (19-20/04/2025). Reunião extraordinária convocada.', 'Em Análise', 'Crítica', 'Paulo Henrique Santos', 2, 8, 7, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=incident.do?sys_id=INC0045387', '2026-04-22 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (6, 'REQ0012445', 'Treinamento em Catalogação de Dados — 3 Turmas TI', 'Contratação de empresa especializada para treinamento de 45 profissionais de TI em catalogação de dados e uso da ferramenta de catálogo corporativo. 3 turmas de 15 pessoas. Período: maio-junho/2025. Aprovado pelo Comitê em abril/2025.', 'Pendente', 'Média', 'Paulo Henrique Santos', 7, 8, 6, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=sc_request.do?sys_id=REQ0012445', '2026-04-20 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (7, 'INC0045102', 'Revisão de Processos de Dados Pessoais em RH (LGPD)', 'Revisão e adequação dos processos de tratamento de dados pessoais nos novos formulários digitais de RH. 12 novos fluxos de dados pessoais identificados e documentados. Prazo de adequação: 30/06/2025.', 'Em Andamento', 'Alta', 'Luciana Pinto', 4, 11, 6, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=incident.do?sys_id=INC0045102', '2026-04-18 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (8, 'REQ0012389', 'Criação de Dashboard de Qualidade — Domínio Financeiro', 'Desenvolvimento de dashboard de monitoramento de qualidade de dados específico para o Domínio Financeiro, com as 82 regras de validação aprovadas no workshop. Integração com Power BI. Prazo: 31/05/2025.', 'Em Andamento', 'Média', 'Mariana Costa Souza', 3, 3, 3, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=sc_request.do?sys_id=REQ0012389', '2026-04-16 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (9, 'INC0044621', 'Publicação da Política de Classificação de Dados v2.1', 'Publicação e comunicação da Política de Classificação de Dados v2.1 aprovada pelo Comitê em março/2025. Inclui o novo nível ''Restrito — Regulatório'' para dados sujeitos à LGPD e normas da ANM. Publicação no portal interno e comunicado às lideranças.', 'Resolvido', 'Alta', 'Mariana Costa Souza', NULL, 3, 6, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=incident.do?sys_id=INC0044621', '2026-03-24 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
INSERT INTO "servicenow_tickets" ("id", "ticketNumber", "title", "description", "status", "priority", "assignedTo", "domainId", "participantId", "meetingId", "externalUrl", "syncedAt", "createdAt", "updatedAt") VALUES (10, 'REQ0012501', 'Inventário Completo de Modelos de IA em Produção', 'Levantamento e documentação completa dos 7 modelos de IA atualmente em produção na Votorantim Cimentos: previsão de demanda, otimização de forno, controle de qualidade, manutenção preditiva, detecção de anomalias, classificação de reclamações e previsão de churn. Prazo: 31/05/2025.', 'Em Andamento', 'Média', 'Diego Barbosa', 7, 10, 4, 'https://votorantimcimentos.service-now.com/nav_to.do?uri=sc_request.do?sys_id=REQ0012501', '2026-04-19 03:11:47', '2026-04-23 07:11:46', '2026-04-23 07:11:46');
