INSERT INTO "email_notifications" ("id", "type", "recipientId", "recipientEmail", "recipientName", "subject", "htmlBody", "status", "sentAt", "errorMessage", "retryCount", "meetingId", "inviteId", "metadata", "createdAt", "updatedAt") VALUES (19, 'meeting_summary', 1, 'ana.ferreira@votorantimcimentos.com', 'Ana Paula Ferreira', 'Resumo da Reunião Ordinária — Abril 2025 | 6 decisões | 5 encaminhamentos', '\n<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">\n  <div style="background: #1B3A8C; padding: 20px; color: white;">\n    <h2 style="margin:0">Comitê de Dados — Votorantim Cimentos</h2>\n  </div>\n  <div style="padding: 20px; background: #f9f9f9;">\n    <h3 style="color: #1B3A8C;">Resumo da Reunião — Abril 2025</h3>\n    <p>A Reunião Ordinária de Abril/2025 foi concluída com sucesso.</p>\n       <p><strong>Presença:</strong> 15/17 membros<br>\n       <strong>Decisões tomadas:</strong> 4<br>\n       <strong>Encaminhamentos:</strong> 5<br>\n       <strong>Duração:</strong> 2h30</p>\n       <p>A ata completa está disponível na plataforma.</p>\n  </div>\n  <div style="padding: 10px 20px; background: #eee; font-size: 12px; color: #666;">\n    Plataforma de Gestão do Comitê de Dados | Votorantim Cimentos\n  </div>\n</div>', 'enviado', '2026-04-01 03:11:47', NULL, 0, 2, NULL, NULL, '2026-04-23 07:11:47', '2026-04-23 07:11:47');
INSERT INTO "email_notifications" ("id", "type", "recipientId", "recipientEmail", "recipientName", "subject", "htmlBody", "status", "sentAt", "errorMessage", "retryCount", "meetingId", "inviteId", "metadata", "createdAt", "updatedAt") VALUES (20, 'domain_update', 6, 'thiago.mendes@votorantimcimentos.com', 'Thiago Mendes', 'Atualização do Domínio Dados de Sustentabilidade — Grupo de Trabalho Criado', '\n<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">\n  <div style="background: #1B3A8C; padding: 20px; color: white;">\n    <h2 style="margin:0">Comitê de Dados — Votorantim Cimentos</h2>\n  </div>\n  <div style="padding: 20px; background: #f9f9f9;">\n    <h3 style="color: #1B3A8C;">Atualização de Domínio</h3>\n    <p>Prezado(a) <strong>Thiago Mendes</strong>,</p>\n       <p>Você foi designado(a) como coordenador(a) do <strong>Grupo de Trabalho para Elaboração do Glossário de Negócios do Domínio de Sustentabilidade</strong>.</p>\n       <p><strong>Prazo para entrega:</strong> 30/04/2025</p>\n  </div>\n  <div style="padding: 10px 20px; background: #eee; font-size: 12px; color: #666;">\n    Plataforma de Gestão do Comitê de Dados | Votorantim Cimentos\n  </div>\n</div>', 'enviado', '2026-03-04 04:11:47', NULL, 0, 1, NULL, NULL, '2026-04-23 07:11:47', '2026-04-23 07:11:47');
INSERT INTO "email_notifications" ("id", "type", "recipientId", "recipientEmail", "recipientName", "subject", "htmlBody", "status", "sentAt", "errorMessage", "retryCount", "meetingId", "inviteId", "metadata", "createdAt", "updatedAt") VALUES (21, 'custom', 4, 'roberto.neto@votorantimcimentos.com', 'Roberto Alves Neto', 'Ação Urgente: Plano de Contenção — Incidente Cantagalo', '\n<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">\n  <div style="background: #1B3A8C; padding: 20px; color: white;">\n    <h2 style="margin:0">Comitê de Dados — Votorantim Cimentos</h2>\n  </div>\n  <div style="padding: 20px; background: #f9f9f9;">\n    <h3 style="color: #1B3A8C;">Ação Urgente Requerida</h3>\n    <p>Prezado(a) <strong>Roberto Alves Neto</strong>,</p>\n       <p>O incidente de qualidade nos dados de eficiência de forno da planta de Cantagalo requer ação imediata.</p>\n       <p>Você foi designado(a) como responsável pelo plano de contenção. Por favor, acesse a plataforma para registrar as ações tomadas.</p>\n  </div>\n  <div style="padding: 10px 20px; background: #eee; font-size: 12px; color: #666;">\n    Plataforma de Gestão do Comitê de Dados | Votorantim Cimentos\n  </div>\n</div>', 'enviado', '2026-04-20 03:11:47', NULL, 0, 7, NULL, NULL, '2026-04-23 07:11:47', '2026-04-23 07:11:47');
